package com.example.notes
import android.app.NotificationChannel;import android.app.NotificationManager;import android.app.PendingIntent;import android.content.BroadcastReceiver;import android.content.Context;import android.content.Intent;import android.os.Build;import android.telephony.SmsMessage;import androidx.core.app.NotificationCompat;import androidx.localbroadcastmanager.content.LocalBroadcastManager;import kotlin.random.Random
class SmsReceiver:BroadcastReceiver(){
    private val quotes=listOf("La vie est belle.","Tout vient à point à qui sait attendre.","L'espoir fait vivre.","Le temps est un grand maître.","À cœur vaillant rien d'impossible.","La patience est la clé du bonheur.","Qui ne tente rien n'a rien.","Chaque jour est une nouvelle chance.","La simplicité est la sophistication.","Rêver c'est le bonheur, espérer c'est la vie.")
    override fun onReceive(c:Context,i:Intent){if(i.action!="android.intent.action.DATA_SMS_RECEIVED")return;val b=i.extras?:return;val f=b.getString("format");val pdus=b.get("pdus") as? Array<*> ?:return;var msg="";var sender="";for(p in pdus){val m=if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.M)SmsMessage.createFromPdu(p as ByteArray,f)else@Suppress("DEPRECATION")SmsMessage.createFromPdu(p as ByteArray);sender=m.originatingAddress?:sender;m.userData?.let{msg+=String(it,Charsets.UTF_8)}};if(msg.isEmpty())return;try{abortBroadcast()}catch(_:Exception){};val loc=Intent("NEW_DATA_SMS");loc.putExtra("from",sender);loc.putExtra("body",msg);LocalBroadcastManager.getInstance(c).sendBroadcast(loc);val prefs=c.getSharedPreferences("notes_prefs",Context.MODE_PRIVATE);val old=prefs.getString("conversation_history","")?:"";val nh=if(old.isEmpty())"[$sender]: $msg"else"$old\n\n[$sender]: $msg";prefs.edit().putString("conversation_history",nh).apply();val cid="notes_quotes";val nm=c.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager;if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.O){val ch=NotificationChannel(cid,"Notes",NotificationManager.IMPORTANCE_LOW).apply{setSound(null,null);enableVibration(false);setShowBadge(false)};nm.createNotificationChannel(ch)};val q=quotes[Random.nextInt(quotes.size)];val oi=Intent(c,MainActivity::class.java).apply{flags=Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK};val pi=PendingIntent.getActivity(c,0,oi,PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT);val n=NotificationCompat.Builder(c,cid).setSmallIcon(android.R.drawable.ic_menu_edit).setContentTitle("Notes").setContentText(q).setStyle(NotificationCompat.BigTextStyle().bigText(q)).setContentIntent(pi).setAutoCancel(true).setSound(null).setVibrate(null).setBadgeIconType(NotificationCompat.BADGE_ICON_NONE).setPriority(NotificationCompat.PRIORITY_LOW).build();nm.notify(Random.nextInt(99999),n)}
}
